def check_odd_composite(k):
    if k <= 1 or k % 2 == 0:
        return None

    # Prime factorization of k
    factors = {}
    n = k
    d = 3
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 2
    if n > 1:
        factors[n] = factors.get(n, 0) + 1

    if len(factors) == 0:
        return False # Should not happen for k > 1

    # Check if k is composite
    is_composite = False
    for p, e in factors.items():
        if e >= 2:
            is_composite = True
            break
    if not is_composite and len(factors) >= 2:
        is_composite = True

    if not is_composite:
        return False # k must be composite

    # Check the equation: product(3*e_i + 1) = product(p_i^e_i)
    lhs = 1
    rhs = 1
    for p, e in factors.items():
        lhs *= (3 * e + 1)
        rhs *= (p ** e)

    return lhs == rhs

# Test small composite odd integers k > 1
print("k=9 (3^2):", check_odd_composite(9))
print("k=15 (3*5):", check_odd_composite(15))
print("k=21 (3*7):", check_odd_composite(21))
